struct ResolutionEsi {
    inner: FakeEsi,
    probes: StdMutex<Vec<Result<ContractItemProbe, EsiError>>>,
    probe_calls: StdMutex<Vec<(i64, Option<String>)>>,
}

struct ResolutionWithTerminalContextEsi {
    inner: ResolutionEsi,
    context: ContractEmbedContext,
}

struct ShortDeadlineResolutionEsi {
    inner: ResolutionEsi,
    budget: Duration,
    context_calls: AtomicU64,
}

#[async_trait]
impl PublicContractEsi for ResolutionEsi {
    async fn regions(&self, etag: Option<&str>) -> Result<EsiResponse<Vec<i64>>, EsiError> {
        self.inner.regions(etag).await
    }

    async fn public_contracts_page(
        &self,
        region_id: i64,
        page: u32,
        etag: Option<&str>,
    ) -> Result<EsiResponse<Vec<PublicContract>>, EsiError> {
        self.inner
            .public_contracts_page(region_id, page, etag)
            .await
    }

    async fn public_contract_items(
        &self,
        contract_id: i64,
        etag: Option<&str>,
    ) -> Result<EsiResponse<Vec<PublicContractItem>>, EsiError> {
        self.inner.public_contract_items(contract_id, etag).await
    }

    async fn public_contract_items_probe(
        &self,
        contract_id: i64,
        etag: Option<&str>,
    ) -> Result<ContractItemProbe, EsiError> {
        self.probe_calls
            .lock()
            .unwrap()
            .push((contract_id, etag.map(str::to_owned)));
        self.probes.lock().unwrap().remove(0)
    }
}

#[async_trait]
impl PublicContractEsi for ResolutionWithTerminalContextEsi {
    async fn regions(&self, etag: Option<&str>) -> Result<EsiResponse<Vec<i64>>, EsiError> {
        self.inner.regions(etag).await
    }

    async fn public_contracts_page(
        &self,
        region_id: i64,
        page: u32,
        etag: Option<&str>,
    ) -> Result<EsiResponse<Vec<PublicContract>>, EsiError> {
        self.inner
            .public_contracts_page(region_id, page, etag)
            .await
    }

    async fn public_contract_items(
        &self,
        contract_id: i64,
        etag: Option<&str>,
    ) -> Result<EsiResponse<Vec<PublicContractItem>>, EsiError> {
        self.inner.public_contract_items(contract_id, etag).await
    }

    async fn public_contract_items_probe(
        &self,
        contract_id: i64,
        etag: Option<&str>,
    ) -> Result<ContractItemProbe, EsiError> {
        self.inner
            .public_contract_items_probe(contract_id, etag)
            .await
    }

    async fn observed_contract_embed_context(
        &self,
        _contract: &PublicContract,
        _items: &[PublicContractItem],
    ) -> Result<EsiResponse<ContractEmbedContext>, EsiError> {
        Ok(EsiResponse::fresh(
            self.context.clone(),
            CacheMetadata::cached_for_seconds(60),
        ))
    }
}

#[async_trait]
impl PublicContractEsi for ShortDeadlineResolutionEsi {
    async fn regions(&self, etag: Option<&str>) -> Result<EsiResponse<Vec<i64>>, EsiError> {
        self.inner.regions(etag).await
    }

    async fn public_contracts_page(
        &self,
        region_id: i64,
        page: u32,
        etag: Option<&str>,
    ) -> Result<EsiResponse<Vec<PublicContract>>, EsiError> {
        self.inner
            .public_contracts_page(region_id, page, etag)
            .await
    }

    async fn public_contract_items(
        &self,
        contract_id: i64,
        etag: Option<&str>,
    ) -> Result<EsiResponse<Vec<PublicContractItem>>, EsiError> {
        self.inner.public_contract_items(contract_id, etag).await
    }

    async fn public_contract_items_probe(
        &self,
        contract_id: i64,
        etag: Option<&str>,
    ) -> Result<ContractItemProbe, EsiError> {
        self.inner
            .public_contract_items_probe(contract_id, etag)
            .await
    }

    fn observed_embed_enrichment_deadline(&self) -> tokio::time::Instant {
        tokio::time::Instant::now() + self.budget
    }

    async fn observed_contract_embed_context_limited_until(
        &self,
        _contract: &PublicContract,
        _items: &[PublicContractItem],
        _limiter: &dyn ContractContextLimiter,
        _deadline: tokio::time::Instant,
    ) -> Result<EsiResponse<ContractEmbedContext>, EsiError> {
        self.context_calls.fetch_add(1, Ordering::Relaxed);
        Err(EsiError::retryable("terminal deadline was renewed", None))
    }
}

struct RemovingDelivery {
    store: ContractCollectionStore,
    sent: StdMutex<Vec<PreparedContractDelivery>>,
}

#[async_trait]
impl ContractDelivery for RemovingDelivery {
    async fn send(
        &self,
        delivery: PreparedContractDelivery,
    ) -> Result<String, ContractDeliveryError> {
        assert!(self
            .store
            .remove_contract_subscription(
                delivery.guild_id,
                delivery.channel_id,
                &delivery.subscription_id,
            )
            .await
            .expect("unsubscribe while a delivery is prepared"));
        self.sent.lock().unwrap().push(delivery);
        Ok("discord-message-id-after-unsubscribe".to_string())
    }
}

#[async_trait]
impl ContractDelivery for RecordingDelivery {
    async fn send(
        &self,
        delivery: PreparedContractDelivery,
    ) -> Result<String, ContractDeliveryError> {
        let record = self
            .store
            .delivery_record(delivery.delivery_id)
            .await
            .expect("read the persisted delivery before Discord is called")
            .expect("delivery exists before Discord is called");
        assert_eq!(record.status, DeliveryStatus::Prepared);
        self.sent.lock().unwrap().push(delivery);
        Ok("discord-message-id".to_string())
    }
}

#[async_trait]
impl ContractDelivery for NotifyingDelivery {
    async fn send(
        &self,
        delivery: PreparedContractDelivery,
    ) -> Result<String, ContractDeliveryError> {
        let record = self
            .store
            .delivery_record(delivery.delivery_id)
            .await
            .expect("read the persisted delivery before Discord is called")
            .expect("delivery exists before Discord is called");
        assert_eq!(record.status, DeliveryStatus::Prepared);
        self.sent.lock().unwrap().push(delivery);
        self.delivered.notify_one();
        Ok("discord-message-id".to_string())
    }
}

#[async_trait]
impl ContractDelivery for FirstDeliveryGate {
    async fn send(
        &self,
        delivery: PreparedContractDelivery,
    ) -> Result<String, ContractDeliveryError> {
        let record = self
            .store
            .delivery_record(delivery.delivery_id)
            .await
            .expect("read the persisted delivery before Discord is called")
            .expect("delivery exists before Discord is called");
        assert_eq!(record.status, DeliveryStatus::Prepared);
        if self.gate_open.swap(false, Ordering::SeqCst) {
            self.entered.notify_one();
            self.release.notified().await;
        }
        self.sent.lock().unwrap().push(delivery);
        Ok("discord-message-id".to_string())
    }
}

#[async_trait]
impl ContractDelivery for NoopDelivery {
    async fn send(
        &self,
        _delivery: PreparedContractDelivery,
    ) -> Result<String, ContractDeliveryError> {
        Ok("ignored".to_string())
    }
}

#[async_trait]
impl ContractDelivery for ScriptedDelivery {
    async fn send(
        &self,
        delivery: PreparedContractDelivery,
    ) -> Result<String, ContractDeliveryError> {
        let record = self
            .store
            .delivery_record(delivery.delivery_id)
            .await
            .expect("read the persisted delivery before Discord is called")
            .expect("delivery exists before Discord is called");
        assert_eq!(record.status, DeliveryStatus::Prepared);
        self.attempts.lock().unwrap().push(delivery);
        self.outcomes.lock().unwrap().remove(0)
    }
}

#[async_trait]
impl ContractDelivery for ScriptedRepairDelivery {
    async fn send(
        &self,
        delivery: PreparedContractDelivery,
    ) -> Result<String, ContractDeliveryError> {
        self.sent.lock().unwrap().push(delivery);
        Err(ContractDeliveryError::permanent(
            "unexpected replacement contract alert",
        ))
    }

    async fn edit(&self, edit: ContractMessageEdit) -> Result<(), ContractDeliveryError> {
        self.edits.lock().unwrap().push(edit);
        self.edit_outcomes.lock().unwrap().remove(0)
    }
}

#[async_trait]
impl ContractDelivery for ReconcilingDelivery {
    async fn send(
        &self,
        delivery: PreparedContractDelivery,
    ) -> Result<String, ContractDeliveryError> {
        self.sent.lock().unwrap().push(delivery);
        Ok("proximity-promotion-message".to_string())
    }

    async fn edit(&self, edit: ContractMessageEdit) -> Result<(), ContractDeliveryError> {
        self.edits.lock().unwrap().push(edit);
        Ok(())
    }
}

#[async_trait]
impl ContractDelivery for ScriptedPromotionRepairDelivery {
    async fn send(
        &self,
        delivery: PreparedContractDelivery,
    ) -> Result<String, ContractDeliveryError> {
        self.sent.lock().unwrap().push(delivery);
        Ok("proximity-promotion-message".to_string())
    }

    async fn edit(&self, edit: ContractMessageEdit) -> Result<(), ContractDeliveryError> {
        self.edits.lock().unwrap().push(edit);
        self.edit_outcomes.lock().unwrap().remove(0)
    }
}

#[async_trait]
impl ContractDelivery for IsolatedRepairDelivery {
    async fn send(
        &self,
        delivery: PreparedContractDelivery,
    ) -> Result<String, ContractDeliveryError> {
        self.sent.lock().unwrap().push(delivery);
        Ok("unrelated-contract-message".to_string())
    }

    async fn edit(&self, edit: ContractMessageEdit) -> Result<(), ContractDeliveryError> {
        self.edits.lock().unwrap().push(edit);
        Err(ContractDeliveryError::permanent(
            "Missing Permissions for the repair",
        ))
    }
}

#[async_trait]
impl ContractDelivery for GatedRepairDelivery {
    async fn send(
        &self,
        _delivery: PreparedContractDelivery,
    ) -> Result<String, ContractDeliveryError> {
        Err(ContractDeliveryError::permanent(
            "unexpected replacement contract alert",
        ))
    }

    async fn edit(&self, edit: ContractMessageEdit) -> Result<(), ContractDeliveryError> {
        self.edits.lock().unwrap().push(edit);
        self.entered.notify_one();
        while !self.released.load(Ordering::SeqCst) {
            self.release.notified().await;
        }
        self.edit_outcome.lock().unwrap().clone()
    }
}

#[async_trait]
impl ContractPingLimiter for RecordingContractPingLimiter {
    async fn try_acquire(&self, channel_id: u64) -> bool {
        self.channels.lock().unwrap().push(channel_id);
        self.outcomes.lock().unwrap().remove(0)
    }
}

impl ContractDeliveryClock for FixedDeliveryClock {
    fn now(&self) -> chrono::DateTime<Utc> {
        *self.0.lock().unwrap()
    }
}

fn contract_subscription(
    id: &str,
    direction: ContractItemDirection,
    type_ids: Vec<i64>,
    ship_group_ids: Vec<i64>,
    listed: ContractEventAction,
) -> ContractSubscription {
    ContractSubscription {
        guild_id: 42,
        channel_id: 77,
        id: id.to_string(),
        description: format!("{id} subscription"),
        filter: ContractFilter::listed_ship(direction, type_ids, ship_group_ids),
        event_actions: ContractEventActions {
            listed,
            ..ContractEventActions::default()
        },
    }
}

fn confirmed_ship_subscription(
    id: &str,
    event_kind: ContractEventKind,
    direction: ContractItemDirection,
    action: ContractEventAction,
) -> ContractSubscription {
    ContractSubscription {
        guild_id: 42,
        channel_id: 77,
        id: id.to_string(),
        description: format!("{id} subscription"),
        filter: ContractFilter {
            root: ContractFilterNode::And(vec![
                ContractFilterNode::Condition(ContractFilterCondition::EventKinds(vec![
                    event_kind,
                ])),
                ContractFilterNode::Condition(ContractFilterCondition::ItemTypes {
                    direction,
                    ids: vec![587],
                }),
            ]),
        },
        event_actions: ContractEventActions {
            listed: ContractEventAction::Ignore,
            sale_confirmed: if event_kind == ContractEventKind::SaleConfirmed {
                action
            } else {
                ContractEventAction::Ignore
            },
            purchase_confirmed: if event_kind == ContractEventKind::PurchaseConfirmed {
                action
            } else {
                ContractEventAction::Ignore
            },
            ..ContractEventActions::default()
        },
    }
}

fn terminal_ship_subscription(
    id: &str,
    event_kind: ContractEventKind,
    action: ContractEventAction,
) -> ContractSubscription {
    ContractSubscription {
        guild_id: 42,
        channel_id: 77,
        id: id.to_string(),
        description: format!("{id} subscription"),
        filter: ContractFilter {
            root: ContractFilterNode::And(vec![
                ContractFilterNode::Condition(ContractFilterCondition::EventKinds(vec![
                    event_kind,
                ])),
                ContractFilterNode::Condition(ContractFilterCondition::ItemTypes {
                    direction: ContractItemDirection::Offered,
                    ids: vec![587],
                }),
            ]),
        },
        event_actions: ContractEventActions {
            listed: ContractEventAction::Ignore,
            expired: if event_kind == ContractEventKind::Expired {
                action
            } else {
                ContractEventAction::Ignore
            },
            closed_outcome_unknown: if event_kind == ContractEventKind::ClosedOutcomeUnknown {
                action
            } else {
                ContractEventAction::Ignore
            },
            ..ContractEventActions::default()
        },
    }
}

fn item_exchange_contract(contract_id: i64) -> PublicContract {
    PublicContract {
        contract_id,
        availability: Some("public".to_string()),
        buyout: None,
        collateral: Some(0.0),
        contract_type: "item_exchange".to_string(),
        date_expired: Utc.with_ymd_and_hms(9999, 12, 31, 23, 59, 59).unwrap(),
        date_issued: Utc.with_ymd_and_hms(2026, 8, 13, 12, 0, 0).unwrap(),
        days_to_complete: 0,
        end_location_id: Some(60_003_760),
        for_corporation: false,
        issuer_corporation_id: 98_000_001,
        issuer_id: 90_000_001,
        price: 1_500_000_000.0,
        reward: 0.0,
        start_location_id: 60_003_760,
        title: Some("this title must not determine the manifest".to_string()),
        volume: 115_000.0,
    }
}

fn expiring_page(expected_pages: u32) -> CacheMetadata {
    CacheMetadata::page_cached_for_seconds(expected_pages, 0)
}

fn expiring_cache() -> CacheMetadata {
    CacheMetadata::cached_for_seconds(0)
}

fn cached_item_metadata(etag: &str, seconds: i64) -> CacheMetadata {
    CacheMetadata {
        etag: Some(etag.to_string()),
        ..CacheMetadata::cached_for_seconds(seconds)
    }
}

fn regional_esi(
    contracts: Vec<PublicContract>,
    items: HashMap<i64, Result<EsiResponse<Vec<PublicContractItem>>, EsiError>>,
) -> FakeEsi {
    FakeEsi {
        regions: vec![10_000_002],
        pages: HashMap::from([(
            (10_000_002, 1),
            Ok(EsiResponse::fresh(contracts, expiring_page(1))),
        )]),
        items,
    }
}

fn position_at_light_years(x: f64) -> SolarSystemPosition {
    SolarSystemPosition {
        x: x * 9_460_730_472_580_800.0,
        y: 0.0,
        z: 0.0,
    }
}

fn offered_ship(record_id: i64) -> PublicContractItem {
    PublicContractItem {
        record_id,
        type_id: 587,
        quantity: 1,
        is_included: true,
        item_id: Some(1_000 + record_id),
        raw_quantity: None,
        is_singleton: None,
        is_blueprint_copy: None,
        material_efficiency: None,
        runs: None,
        time_efficiency: None,
    }
}

fn requested_ship(record_id: i64) -> PublicContractItem {
    PublicContractItem {
        is_included: false,
        ..offered_ship(record_id)
    }
}

#[tokio::test]
async fn contract_subscription_filters_share_listing_presentation_at_the_collector_seam() {
    let database = TemporaryDatabase::new().await;
    let store = database.store().await;
    let server = GatedObservedLocationEnrichmentHttpServer::start_ungated();
    let esi = Arc::new(
        HttpPublicContractEsi::with_base_url(&server.base_url, Duration::from_secs(1))
            .expect("construct controlled public ESI client"),
    );

    ContractCollector::new(store.clone(), esi.clone())
        .collect_cycle()
        .await
        .expect("establish the silent public-contract baseline");

    let subscriptions = [
        (
            "region",
            77,
            ContractFilterNode::Condition(ContractFilterCondition::Regions(vec![10_000_002])),
        ),
        (
            "issuer",
            78,
            ContractFilterNode::Condition(ContractFilterCondition::IssuerCharacters(vec![
                90_000_001,
            ])),
        ),
        (
            "item",
            79,
            ContractFilterNode::Condition(ContractFilterCondition::ItemTypes {
                direction: ContractItemDirection::Offered,
                ids: vec![587],
            }),
        ),
        (
            "proximity",
            80,
            ContractFilterNode::Condition(ContractFilterCondition::LyRangeFrom(vec![
                config::SystemRange {
                    system_id: 30_000_142,
                    range: 1.0,
                },
            ])),
        ),
    ];
    for (id, channel_id, root) in subscriptions {
        store
            .upsert_contract_subscription(&ContractSubscription {
                guild_id: 42,
                channel_id,
                id: id.to_string(),
                description: format!("{id} contract subscription"),
                filter: ContractFilter { root },
                event_actions: ContractEventActions {
                    listed: ContractEventAction::Post,
                    sale_confirmed: ContractEventAction::PostAndPing,
                    ..ContractEventActions::default()
                },
            })
            .await
            .expect("persist an equivalent contract subscription");
    }
    let delivery = Arc::new(RecordingDelivery {
        store: store.clone(),
        sent: StdMutex::new(Vec::new()),
    });

    ContractCollector::new(store, esi)
        .with_notifications(
            Arc::new(StaticShipGroups(HashMap::from([(587, 659)]))),
            delivery.clone(),
        )
        .collect_cycle()
        .await
        .expect("collect the equivalent listed contract subscriptions");

    let expected_description = "`<url=\"contract:0//45\">Rifter - Jita</url>`\n**in:** [Jita](http://evemaps.dotlan.net/system/30000142) ([The Forge](http://evemaps.dotlan.net/region/10000002))\n**on:** [Jita IV Moon 4 Caldari Navy Assembly Plant](https://zkillboard.com/location/60003760/)";
    let expected_range = "\n**range:** 0.0 LY from Jita ([Supers](https://evemaps.dotlan.net/jump/Nyx,555/Jita:Jita)|[FAX](https://evemaps.dotlan.net/jump/Lif,555/Jita:Jita)|[Blops](https://evemaps.dotlan.net/jump/Sin,555/Jita:Jita))";
    let sent = delivery.sent.lock().unwrap();
    assert_eq!(sent.len(), 4);
    for (id, channel_id, has_range) in [
        ("region", 77, false),
        ("issuer", 78, false),
        ("item", 79, false),
        ("proximity", 80, true),
    ] {
        let notification = sent
            .iter()
            .find(|notification| {
                notification.subscription_id == id && notification.channel_id == channel_id
            })
            .expect("deliver the matched contract subscription");
        let embed = contract_notification_embed(&notification.message).0;
        let description = embed["description"]
            .as_str()
            .expect("render a compact contract description");
        assert_eq!(
            description,
            if has_range {
                format!("{expected_description}{expected_range}")
            } else {
                expected_description.to_string()
            },
            "{id} uses the shared compact presentation"
        );
        assert_eq!(
            notification.message.author.as_deref(),
            Some("Public Contract\nissuer: [Issuer Alliance] Issuer"),
            "{id} uses the contextual issuer grammar"
        );
        assert_eq!(
            notification.message.presentation_revision, 5,
            "{id} uses the current shared presentation revision"
        );
        assert!(
            !notification.ping,
            "{id} does not inherit acceptance-only ping eligibility for a listing"
        );
        assert_eq!(notification.message.fields.len(), 0, "{id} remains compact");
        let serialized = serde_json::to_string(&embed).expect("serialize the compact embed");
        for prohibited in [
            "Acceptor",
            "90000001",
            "98000001",
            "99000111",
            "Unknown",
            "evidence class",
            "HTTP",
        ] {
            assert!(
                !serialized.contains(prohibited),
                "{id} must omit {prohibited}: {serialized}"
            );
        }
    }
    drop(sent);

    server.finish();
    database.destroy().await;
}

#[tokio::test]
async fn contract_subscription_filters_keep_canonical_multiship_presentation_at_the_collector_seam()
{
    let database = TemporaryDatabase::new().await;
    let store = database.store().await;
    let baseline = item_exchange_contract(44);
    let listed = item_exchange_contract(45);
    let ragnarok = PublicContractItem {
        type_id: 19_720,
        ..offered_ship(2)
    };
    ContractCollector::new(
        store.clone(),
        Arc::new(regional_esi(
            vec![baseline.clone()],
            HashMap::from([(
                baseline.contract_id,
                Ok(EsiResponse::fresh(vec![offered_ship(1)], expiring_cache())),
            )]),
        )),
    )
    .collect_cycle()
    .await
    .expect("establish the silent canonical multiship baseline");
    let snapshot_pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("connect to retain canonical multiship names");
    sqlx::query("INSERT INTO contract_observed_embed_contexts (region_id, contract_id, context, observed_at) VALUES ($1,$2,$3,now())")
        .bind(10_000_002_i64)
        .bind(listed.contract_id)
        .bind(serde_json::to_value(ContractEmbedContext {
            item_names: BTreeMap::from([
                (587, "Rifter".to_string()),
                (19_720, "Ragnarok".to_string()),
            ]),
            ..ContractEmbedContext::default()
        }).expect("serialize canonical multiship names"))
        .execute(&snapshot_pool)
        .await
        .expect("retain canonical multiship names");
    snapshot_pool.close().await;
    for (id, root) in [
        (
            "region",
            ContractFilterNode::Condition(ContractFilterCondition::Regions(vec![10_000_002])),
        ),
        (
            "issuer",
            ContractFilterNode::Condition(ContractFilterCondition::IssuerCharacters(vec![
                90_000_001,
            ])),
        ),
        (
            "rifter-only-item",
            ContractFilterNode::Condition(ContractFilterCondition::ItemTypes {
                direction: ContractItemDirection::Offered,
                ids: vec![587],
            }),
        ),
        (
            "proximity",
            ContractFilterNode::Condition(ContractFilterCondition::LyRangeFrom(vec![
                config::SystemRange {
                    system_id: 30_000_142,
                    range: 1.0,
                },
            ])),
        ),
    ] {
        store
            .upsert_contract_subscription(&ContractSubscription {
                guild_id: 42,
                channel_id: 77,
                id: id.to_string(),
                description: format!("{id} canonical multiship subscription"),
                filter: ContractFilter { root },
                event_actions: ContractEventActions {
                    listed: ContractEventAction::Post,
                    ..ContractEventActions::default()
                },
            })
            .await
            .expect("persist canonical multiship subscription");
    }
    let delivery = Arc::new(RecordingDelivery {
        store: store.clone(),
        sent: StdMutex::new(Vec::new()),
    });
    ContractCollector::new(
        store,
        Arc::new(PositionEsi {
            inner: regional_esi(
                vec![baseline, listed.clone()],
                HashMap::from([
                    (
                        44,
                        Ok(EsiResponse::fresh(vec![offered_ship(1)], expiring_cache())),
                    ),
                    (
                        listed.contract_id,
                        Ok(EsiResponse::fresh(
                            vec![offered_ship(1), ragnarok],
                            expiring_cache(),
                        )),
                    ),
                ]),
            ),
            contexts: HashMap::from([(
                listed.contract_id,
                ContractObservationContext {
                    solar_system_id: Some(30_000_142),
                    solar_system_position: Some(position_at_light_years(0.0)),
                    ..ContractObservationContext::default()
                },
            )]),
            positions: HashMap::from([(30_000_142, position_at_light_years(0.0))]),
            position_calls: StdMutex::new(Vec::new()),
        }),
    )
    .with_notifications(
        Arc::new(StaticShipGroups(HashMap::from([(587, 659), (19_720, 30)]))),
        delivery.clone(),
    )
    .collect_cycle()
    .await
    .expect("collect canonical multiship subscriptions");
    let sent = delivery.sent.lock().unwrap();
    assert_eq!(sent.len(), 4);
    for id in ["region", "issuer", "rifter-only-item", "proximity"] {
        let notification = sent
            .iter()
            .find(|notification| notification.subscription_id == id)
            .expect("each independent filter stays eligible");
        assert_eq!(notification.message.title, "Ragnarok listed for 1.5B ISK");
        assert_eq!(
            notification.message.thumbnail_url.as_deref(),
            Some("https://images.evetech.net/types/19720/icon?size=64")
        );
        assert!(!notification.ping);
    }
    drop(sent);
    database.destroy().await;
}

#[tokio::test]
async fn historical_rerender_without_a_thumbnail_keeps_the_live_multiship_primary() {
    let database = TemporaryDatabase::new().await;
    let store = database.store().await;
    let baseline = item_exchange_contract(44);
    let listed = item_exchange_contract(45);
    let ragnarok = PublicContractItem {
        type_id: 19_720,
        ..offered_ship(2)
    };
    ContractCollector::new(
        store.clone(),
        Arc::new(NamedFakeEsi {
            inner: regional_esi(
                vec![baseline.clone()],
                HashMap::from([(
                    baseline.contract_id,
                    Ok(EsiResponse::fresh(vec![offered_ship(1)], expiring_cache())),
                )]),
            ),
        }),
    )
    .collect_cycle()
    .await
    .expect("establish the silent multiship baseline");
    store
        .upsert_contract_subscription(&ContractSubscription {
            guild_id: 42,
            channel_id: 77,
            id: "historical-multiship".to_string(),
            description: "historical multiship rerender".to_string(),
            filter: ContractFilter {
                root: ContractFilterNode::Condition(ContractFilterCondition::Regions(vec![
                    10_000_002,
                ])),
            },
            event_actions: ContractEventActions {
                listed: ContractEventAction::Post,
                ..ContractEventActions::default()
            },
        })
        .await
        .expect("persist the live multiship subscription");
    let delivery = Arc::new(RecordingDelivery {
        store: store.clone(),
        sent: StdMutex::new(Vec::new()),
    });
    ContractCollector::new(
        store.clone(),
        Arc::new(NamedFakeEsi {
            inner: regional_esi(
                vec![baseline, listed.clone()],
                HashMap::from([
                    (
                        44,
                        Ok(EsiResponse::fresh(vec![offered_ship(1)], expiring_cache())),
                    ),
                    (
                        listed.contract_id,
                        Ok(EsiResponse::fresh(
                            vec![offered_ship(1), ragnarok],
                            expiring_cache(),
                        )),
                    ),
                ]),
            ),
        }),
    )
    .with_notifications(
        Arc::new(StaticShipGroups(HashMap::from([(587, 659), (19_720, 30)]))),
        delivery.clone(),
    )
    .collect_cycle()
    .await
    .expect("render the live multiship listing");
    let live = delivery.sent.lock().unwrap()[0].clone();
    assert_eq!(live.message.title, "Ragnarok listed for 1.5B ISK");
    assert_eq!(
        live.message.thumbnail_url.as_deref(),
        Some("https://images.evetech.net/types/19720/icon?size=64")
    );
    let mut retained_without_thumbnail = live.message.clone();
    retained_without_thumbnail.title = "Public contract listed for 1.5B ISK".to_string();
    retained_without_thumbnail.description =
        Some("`<url=\"contract:0//45\">Public contract - Jita</url>`".to_string());
    retained_without_thumbnail.fields.clear();
    retained_without_thumbnail.thumbnail_url = None;
    retained_without_thumbnail.presentation_revision = 4;
    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("connect to remove the retained thumbnail");
    sqlx::query(
        "UPDATE contract_outbound_deliveries SET message = $2, discord_message_id = $3 WHERE id = $1",
    )
    .bind(live.delivery_id)
    .bind(
        serde_json::to_value(retained_without_thumbnail)
            .expect("serialize retained thumbnail-less message"),
    )
    .bind(rerender_test_discord_message_id(1))
        .execute(&pool)
        .await
        .expect("retain the generic revision-four historical message");
    pool.close().await;
    let delivery_id = live.delivery_id.to_string();
    let rerender_arguments = [
        "rerender",
        "--channel",
        "77",
        "--delivery-ids",
        delivery_id.as_str(),
        "--queue",
        "--actor",
        CONTRACT_DELIVERY_OPERATOR_ACTOR,
    ];
    let missing_group_error =
        execute_operator_delivery_cli_with_region_name_lookup_and_ship_groups(
            &store,
            &rerender_arguments,
            Utc::now(),
            &HashMap::from([(10_000_002, "The Forge".to_string())]),
            None,
            &StaticShipGroups(HashMap::from([(587, 659)])),
        )
        .await
        .expect_err("reject a rerender whose canonical item lacks a cached group");
    assert!(missing_group_error.contains("lacks cached ship group for type 19720"));
    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("inspect the rejected rerender");
    let rejected_state: (String, Option<Value>) = sqlx::query_as(
        "SELECT repair_status, desired_message FROM contract_outbound_deliveries WHERE id = $1",
    )
    .bind(live.delivery_id)
    .fetch_one(&pool)
    .await
    .expect("read the atomically rejected rerender");
    assert_eq!(rejected_state.0, "none");
    assert!(rejected_state.1.is_none());
    pool.close().await;
    execute_operator_delivery_cli_with_region_name_lookup_and_ship_groups(
        &store,
        &rerender_arguments,
        Utc::now(),
        &HashMap::from([(10_000_002, "The Forge".to_string())]),
        None,
        &StaticShipGroups(HashMap::from([(587, 659), (19_720, 30)])),
    )
    .await
    .expect("queue the generic revision-four historical rerender");
    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("read the rerendered historical message");
    let rerendered: ContractNotificationMessage = serde_json::from_value(
        sqlx::query_scalar::<_, Value>(
            "SELECT desired_message FROM contract_outbound_deliveries WHERE id = $1",
        )
        .bind(live.delivery_id)
        .fetch_one(&pool)
        .await
        .expect("read queued desired message"),
    )
    .expect("deserialize rerendered historical message");
    assert!(rerendered.title.starts_with(&live.message.title));
    assert_eq!(rerendered.thumbnail_url, live.message.thumbnail_url);
    assert_eq!(
        rerendered.presentation_revision,
        CONTRACT_NOTIFICATION_PRESENTATION_REVISION
    );
    assert!(rerendered.title.contains("1.5B ISK"));
    pool.close().await;
    database.destroy().await;
}

#[tokio::test]
async fn public_contract_listing_embed_uses_the_compact_killfeed_shell_at_the_collector_seam() {
    let database = TemporaryDatabase::new().await;
    let store = database.store().await;
    let server = GatedObservedLocationEnrichmentHttpServer::start_ungated();
    let esi = Arc::new(
        HttpPublicContractEsi::with_base_url(&server.base_url, Duration::from_secs(1))
            .expect("construct controlled public ESI client"),
    );

    ContractCollector::new(store.clone(), esi.clone())
        .collect_cycle()
        .await
        .expect("establish the silent public-contract baseline");
    store
        .upsert_contract_subscription(&contract_subscription(
            "compact-shell",
            ContractItemDirection::Offered,
            vec![587],
            vec![],
            ContractEventAction::Post,
        ))
        .await
        .expect("persist the listing subscription");
    let delivery = Arc::new(RecordingDelivery {
        store: store.clone(),
        sent: StdMutex::new(Vec::new()),
    });

    ContractCollector::new(store, esi)
        .with_notifications(
            Arc::new(StaticShipGroups(HashMap::from([(587, 659)]))),
            delivery.clone(),
        )
        .collect_cycle()
        .await
        .expect("collect the listed public contract and prepare its delivery");

    let prepared = delivery.sent.lock().unwrap();
    assert_eq!(prepared.len(), 1);
    let embed = contract_notification_embed(&prepared[0].message).0;
    assert_eq!(
        embed["description"].as_str(),
        Some(
            "`<url=\"contract:0//45\">Rifter - Jita</url>`\n**in:** [Jita](http://evemaps.dotlan.net/system/30000142) ([The Forge](http://evemaps.dotlan.net/region/10000002))\n**on:** [Jita IV Moon 4 Caldari Navy Assembly Plant](https://zkillboard.com/location/60003760/)"
        )
    );
    assert_eq!(embed["footer"]["text"].as_str(), Some("Contract #45"));
    assert_eq!(embed["timestamp"].as_str(), Some("2026-08-13T12:00:00Z"));
    assert!(embed["author"]["name"]
        .as_str()
        .is_some_and(|author| author.lines().count() == 2 && author.contains("Issuer")));
    assert!(
        embed
            .get("fields")
            .and_then(Value::as_array)
            .map_or(0, Vec::len)
            <= 3
    );
    let content_lines = embed["description"]
        .as_str()
        .map(str::lines)
        .map(Iterator::count)
        .unwrap_or(0)
        + embed
            .get("fields")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(|field| field["value"].as_str())
            .map(str::lines)
            .map(Iterator::count)
            .sum::<usize>();
    assert!(content_lines <= 7);
    assert!(!serde_json::to_string(&embed)
        .expect("serialize the contract embed")
        .contains("<t:"));

    drop(prepared);
    server.finish();
    database.destroy().await;
}

#[tokio::test]
async fn public_listing_beyond_the_snapshot_cap_still_waits_for_enrichment() {
    let database = TemporaryDatabase::new().await;
    let store = database.store().await;
    let server =
        GatedObservedLocationEnrichmentHttpServer::start_with_more_listings_than_the_snapshot_cap();
    let esi = Arc::new(
        HttpPublicContractEsi::with_base_url(&server.base_url, Duration::from_secs(2))
            .expect("construct controlled public ESI client"),
    );

    ContractCollector::new(store.clone(), esi.clone())
        .collect_cycle()
        .await
        .expect("establish the silent public-contract baseline");
    store
        .upsert_contract_subscription(&ContractSubscription {
            guild_id: 42,
            channel_id: 77,
            id: "region-only-after-snapshot-cap".to_string(),
            description: "region-only-after-snapshot-cap subscription".to_string(),
            filter: ContractFilter {
                root: ContractFilterNode::And(vec![
                    ContractFilterNode::Condition(ContractFilterCondition::EventKinds(vec![
                        ContractEventKind::Listed,
                    ])),
                    ContractFilterNode::Condition(ContractFilterCondition::Regions(vec![
                        10_000_002,
                    ])),
                ]),
            },
            event_actions: ContractEventActions {
                listed: ContractEventAction::Post,
                ..ContractEventActions::default()
            },
        })
        .await
        .expect("persist the region-only listing subscription");
    let delivery = Arc::new(RecordingDelivery {
        store: store.clone(),
        sent: StdMutex::new(Vec::new()),
    });

    ContractCollector::new(store.clone(), esi)
        .with_notifications(
            Arc::new(StaticShipGroups(HashMap::from([(587, 659)]))),
            delivery.clone(),
        )
        .collect_cycle()
        .await
        .expect("collect listings past the observation snapshot cap");

    let sent = delivery.sent.lock().unwrap();
    assert_eq!(sent.len(), 9);
    let ninth = sent
        .iter()
        .find(|notification| {
            notification
                .message
                .description
                .as_deref()
                .is_some_and(|description| description.contains("contract:0//53"))
        })
        .expect("deliver the listing beyond the snapshot cap");
    let embed = contract_notification_embed(&ninth.message).0;
    assert_eq!(
        embed["description"].as_str(),
        Some(
            "`<url=\"contract:0//53\">Rifter - Jita</url>`\n**in:** [Jita](http://evemaps.dotlan.net/system/30000142) ([The Forge](http://evemaps.dotlan.net/region/10000002))\n**on:** [Jita IV Moon 4 Caldari Navy Assembly Plant](https://zkillboard.com/location/60003760/)"
        )
    );
    drop(sent);
    let retained = store
        .observed_embed_context(10_000_002, 53)
        .await
        .expect("inspect the retained context beyond the snapshot cap")
        .expect("retain context beyond the snapshot cap");
    assert_eq!(
        retained.location.location_name.as_deref(),
        Some("Jita IV - Moon 4 - Caldari Navy Assembly Plant")
    );
    assert_eq!(retained.issuer_character_name.as_deref(), Some("Issuer"));

    server.finish();
    database.destroy().await;
}

#[tokio::test]
async fn public_station_listing_waits_for_concurrent_observed_location_enrichment_before_discord_delivery(
) {
    let database = TemporaryDatabase::new().await;
    let store = database.store().await;
    let server = GatedObservedLocationEnrichmentHttpServer::start();
    let esi = Arc::new(
        HttpPublicContractEsi::with_base_url(&server.base_url, Duration::from_secs(2))
            .expect("construct gated public ESI client"),
    );

    ContractCollector::new(store.clone(), esi.clone())
        .collect_cycle()
        .await
        .expect("establish the silent public-contract baseline");
    store
        .upsert_contract_subscription(&contract_subscription(
            "synchronous-public-station",
            ContractItemDirection::Offered,
            vec![587],
            vec![],
            ContractEventAction::Post,
        ))
        .await
        .expect("persist the matched public-station subscription");
    let delivery = Arc::new(RecordingDelivery {
        store: store.clone(),
        sent: StdMutex::new(Vec::new()),
    });
    let collector = ContractCollector::new(store.clone(), esi).with_notifications(
        Arc::new(StaticShipGroups(HashMap::from([(587, 659)]))),
        delivery.clone(),
    );
    let mut cycle = tokio::spawn(async move { collector.collect_cycle().await });

    tokio::time::timeout(Duration::from_secs(2), server.station_started.notified())
        .await
        .expect("the first Observed Location step starts");
    let observed_affiliation_started = tokio::time::timeout(
        Duration::from_millis(500),
        server.observed_affiliation_started.notified(),
    )
    .await;
    let names_started =
        tokio::time::timeout(Duration::from_millis(500), server.names_started.notified()).await;
    assert!(delivery.sent.lock().unwrap().is_empty());
    assert!(store
        .delivery_records()
        .await
        .expect("inspect the retained delivery queue before enrichment completes")
        .is_empty());

    server.release_station();
    let cycle_result = tokio::time::timeout(Duration::from_secs(5), &mut cycle).await;
    if cycle_result.is_err() {
        cycle.abort();
        let _ = cycle.await;
    }
    cycle_result
        .expect("finish enriched public-station collection after releasing enrichment")
        .expect("join enriched public-station collection")
        .expect("finish enriched public-station collection");

    assert!(
        observed_affiliation_started.is_ok(),
        "Observed Affiliation resolution starts while the first Observed Location step is held"
    );
    assert!(
        names_started.is_ok(),
        "issuer and item-name resolution starts while the first Observed Location step is held"
    );
    let sent = delivery.sent.lock().unwrap();
    assert_eq!(sent.len(), 1);
    let embed = contract_notification_embed(&sent[0].message).0;
    assert_eq!(
        embed["description"].as_str(),
        Some(
            "`<url=\"contract:0//45\">Rifter - Jita</url>`\n**in:** [Jita](http://evemaps.dotlan.net/system/30000142) ([The Forge](http://evemaps.dotlan.net/region/10000002))\n**on:** [Jita IV Moon 4 Caldari Navy Assembly Plant](https://zkillboard.com/location/60003760/)"
        )
    );
    assert_eq!(
        embed["author"]["name"].as_str(),
        Some("Public Contract\nissuer: [Issuer Alliance] Issuer")
    );
    assert!(!serde_json::to_string(&embed)
        .expect("serialize enriched public-station embed")
        .contains("Unknown"));
    drop(sent);

    let retained = store
        .observed_embed_context(10_000_002, 45)
        .await
        .expect("read retained enrichment evidence")
        .expect("retain enrichment evidence before delivery");
    assert!(retained.observed_at.is_some());
    assert_eq!(retained.issuer_alliance_id, Some(99_000_111));
    assert_eq!(retained.issuer_character_name.as_deref(), Some("Issuer"));
    assert_eq!(
        retained.issuer_corporation_name.as_deref(),
        Some("Issuer Corp")
    );
    assert_eq!(
        retained.issuer_alliance_name.as_deref(),
        Some("Issuer Alliance")
    );
    assert_eq!(
        retained.issuer_identity_provenance,
        Some(IssuerIdentityProvenance::PublicEsi)
    );
    assert_eq!(
        retained.location.location_name.as_deref(),
        Some("Jita IV - Moon 4 - Caldari Navy Assembly Plant")
    );
    assert_eq!(retained.location.solar_system_name.as_deref(), Some("Jita"));
    assert_eq!(retained.location.region_name.as_deref(), Some("The Forge"));
    let verification_pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("connect to inspect retained public contract identifiers");
    let persisted_event: ContractEvent = serde_json::from_value(
        sqlx::query_scalar::<_, Value>(
            "SELECT event FROM contract_outbound_deliveries WHERE contract_id = $1 ORDER BY id DESC LIMIT 1",
        )
        .bind(45_i64)
        .fetch_one(&verification_pool)
        .await
        .expect("read the serialized delivered public-contract event"),
    )
    .expect("deserialize the serialized delivered public-contract event");
    verification_pool.close().await;
    assert_eq!(persisted_event.contract.issuer_id, 90_000_001);
    assert_eq!(persisted_event.contract.issuer_corporation_id, 98_000_001);
    assert!(persisted_event.embed_context.observed_at.is_some());
    assert_eq!(
        persisted_event
            .embed_context
            .issuer_character_name
            .as_deref(),
        Some("Issuer")
    );
    assert_eq!(
        persisted_event
            .embed_context
            .issuer_corporation_name
            .as_deref(),
        Some("Issuer Corp")
    );
    assert_eq!(
        persisted_event
            .embed_context
            .issuer_alliance_name
            .as_deref(),
        Some("Issuer Alliance")
    );
    assert_eq!(
        persisted_event.embed_context.issuer_identity_provenance,
        Some(IssuerIdentityProvenance::PublicEsi)
    );
    let evidence = LocationEvidenceService::new(&store)
        .resolve(60_003_760, Utc::now())
        .await
        .expect("read retained Observed Location evidence")
        .expect("retain Observed Location station provenance");
    assert_eq!(evidence.evidence_class, LocationEvidenceClass::PublicNpc);
    assert_eq!(evidence.station_id, Some(60_003_760));
    assert_eq!(evidence.solar_system_id, 30_000_142);
    assert_eq!(evidence.region_id, Some(10_000_002));

    let requests = server.requests.lock().unwrap();
    let station = requests
        .iter()
        .position(|request| request.starts_with("GET /universe/stations/60003760/"))
        .expect("station request");
    let system = requests
        .iter()
        .position(|request| request.starts_with("GET /universe/systems/30000142/"))
        .expect("system request");
    let constellation = requests
        .iter()
        .position(|request| request.starts_with("GET /universe/constellations/20000020/"))
        .expect("constellation request");
    let region = requests
        .iter()
        .position(|request| request.starts_with("GET /universe/regions/10000002/"))
        .expect("region request");
    assert!(station < system && system < constellation && constellation < region);
    assert!(requests
        .iter()
        .all(|request| !request.to_ascii_lowercase().contains("authorization:")));
    drop(requests);

    server.finish();
    database.destroy().await;
}

