    zero_isk.date_expired = Utc::now() + chrono::Duration::hours(1);
    zero_isk.price = 0.0;
    let mut malformed_isk = item_exchange_contract(47);
    malformed_isk.date_expired = Utc::now() + chrono::Duration::hours(1);
    malformed_isk.price = -1.0;
