#[tokio::test]
async fn legacy_contract_embed_is_repaired_in_place_with_current_presentation_and_retained_proximity_state(
) {
    let database = TemporaryDatabase::new().await;
    let store = database.store().await;
    let baseline = item_exchange_contract(44);
    let listed = item_exchange_contract(45);
    ContractCollector::new(
        store.clone(),
        Arc::new(NamedFakeEsi {
            inner: regional_esi(
                vec![baseline.clone()],
                HashMap::from([(
                    baseline.contract_id,
                    Ok(EsiResponse::fresh(vec![offered_ship(1)], expiring_cache())),
                )]),
            ),
        }),
    )
    .collect_cycle()
    .await
    .expect("establish the silent public-contract baseline");
    store
        .upsert_contract_subscription(&contract_subscription(
            "legacy-presentation-repair",
            ContractItemDirection::Offered,
            vec![587],
            vec![],
            ContractEventAction::PostAndPingEveryone,
        ))
        .await
        .expect("persist the retained contract subscription");

    let original_delivery = Arc::new(RecordingDelivery {
        store: store.clone(),
        sent: StdMutex::new(Vec::new()),
    });
    ContractCollector::new(
        store.clone(),
        Arc::new(NamedFakeEsi {
            inner: regional_esi(
                vec![baseline, listed.clone()],
                HashMap::from([
                    (
                        44,
                        Ok(EsiResponse::fresh(vec![offered_ship(1)], expiring_cache())),
                    ),
                    (
                        listed.contract_id,
                        Ok(EsiResponse::fresh(vec![offered_ship(2)], expiring_cache())),
                    ),
                ]),
            ),
        }),
    )
    .with_notifications(
        Arc::new(StaticShipGroups(HashMap::from([(587, 659)]))),
        original_delivery.clone(),
    )
    .collect_cycle()
    .await
    .expect("send the original retained listing");
    let delivery_id = original_delivery.sent.lock().unwrap()[0].delivery_id;

    let legacy_message = serde_json::json!({
        "title": "Legacy Rifter listed",
        "description": "legacy location and address",
        "fields": [
            { "name": "Listing time", "value": "legacy listing time", "inline": false },
            { "name": "History", "value": "legacy history", "inline": false },
            { "name": "Alert", "value": "Proximity-Verified: Out of Range", "inline": false }
        ],
        "author": "legacy author",
        "thumbnail_url": "https://images.example.test/legacy.png",
        "footer": "legacy footer",
        "timestamp": "2026-08-01T00:00:00Z"
    });
    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("connect to seed the legacy retained message");
    sqlx::query("UPDATE contract_outbound_deliveries SET message = $2 WHERE id = $1")
        .bind(delivery_id)
        .bind(&legacy_message)
        .execute(&pool)
        .await
        .expect("replace the original render with a legacy serialized message");
    sqlx::query("INSERT INTO contract_deferred_subscription_matches (guild_id, channel_id, subscription_id, contract_id, event_kind, event, proximity_unverified) SELECT guild_id, channel_id, subscription_id, contract_id, event_kind, event, FALSE FROM contract_outbound_deliveries WHERE id = $1")
        .bind(delivery_id)
        .execute(&pool)
        .await
        .expect("schedule the ordinary deferred reevaluation");
    let persisted_legacy: Value =
        sqlx::query_scalar("SELECT message FROM contract_outbound_deliveries WHERE id = $1")
            .bind(delivery_id)
            .fetch_one(&pool)
            .await
            .expect("read the legacy serialized message");
    assert_eq!(
        serde_json::from_value::<ContractNotificationMessage>(persisted_legacy)
            .expect("existing serialized messages remain readable")
            .presentation_revision,
        0,
        "an absent serialized revision is obsolete"
    );
    pool.close().await;

    let repair_delivery = Arc::new(ScriptedRepairDelivery {
        sent: StdMutex::new(Vec::new()),
        edits: StdMutex::new(Vec::new()),
        edit_outcomes: StdMutex::new(vec![Ok(())]),
    });
    ContractCollector::new(
        store.clone(),
        Arc::new(NamedFakeEsi {
            inner: regional_esi(
                vec![],
                HashMap::from([
                    (
                        44,
                        Err(EsiError::retryable("terminal probe deferred", None)),
                    ),
                    (
                        listed.contract_id,
                        Err(EsiError::retryable("terminal probe deferred", None)),
                    ),
                ]),
            ),
        }),
    )
    .with_notifications(
        Arc::new(StaticShipGroups(HashMap::from([(587, 659)]))),
        repair_delivery.clone(),
    )
    .collect_cycle()
    .await
    .expect("reevaluate and durably repair the retained listing");

    let edits = repair_delivery.edits.lock().unwrap();
    assert_eq!(edits.len(), 1, "one retained Discord message is edited");
    let edit = &edits[0];
    assert_eq!(edit.delivery_id, delivery_id);
    assert_eq!(edit.contract_id, listed.contract_id);
    assert_eq!(edit.event_kind, ContractEventKind::Listed);
    assert_eq!(edit.discord_message_id, "discord-message-id");
    assert_eq!(
        edit.message.presentation_revision,
        CONTRACT_NOTIFICATION_PRESENTATION_REVISION
    );
    assert_ne!(edit.message.title, "Legacy Rifter listed");
    assert_ne!(
        edit.message.description.as_deref(),
        Some("legacy location and address")
    );
    assert_ne!(edit.message.author.as_deref(), Some("legacy author"));
    assert_ne!(
        edit.message.thumbnail_url.as_deref(),
        Some("https://images.example.test/legacy.png")
    );
    assert_ne!(edit.message.footer.as_deref(), Some("legacy footer"));
    assert_eq!(edit.message.timestamp, Some(listed.date_issued));
    assert_eq!(
        edit.message.fields,
        vec![killbot_rust::contract_intelligence::ContractEmbedField {
            name: "Alert".to_string(),
            value: "Proximity-Verified: Out of Range".to_string(),
            inline: false,
        }],
        "only stateful proximity survives a presentation repair"
    );
    drop(edits);
    assert!(
        repair_delivery.sent.lock().unwrap().is_empty(),
        "a repair never creates a replacement post"
    );

    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("inspect the repaired retained delivery");
    let identity: (i64, i64, String, String, bool, String, String) = sqlx::query_as(
        "SELECT id, contract_id, event_kind, discord_message_id, ping, ping_type, delivery_nonce FROM contract_outbound_deliveries WHERE id = $1",
    )
    .bind(delivery_id)
    .fetch_one(&pool)
    .await
    .expect("read the stable retained delivery identity");
    assert_eq!(
        identity,
        (
            delivery_id,
            listed.contract_id,
            "listed".to_string(),
            "discord-message-id".to_string(),
            true,
            "everyone".to_string(),
            format!("ci-{delivery_id}"),
        )
    );
    let repaired: Value =
        sqlx::query_scalar("SELECT message FROM contract_outbound_deliveries WHERE id = $1")
            .bind(delivery_id)
            .fetch_one(&pool)
            .await
            .expect("read the repaired serialized message");
    assert_eq!(
        serde_json::from_value::<ContractNotificationMessage>(repaired)
            .expect("read the upgraded serialized message")
            .presentation_revision,
        CONTRACT_NOTIFICATION_PRESENTATION_REVISION
    );
    pool.close().await;
    database.destroy().await;
}

#[tokio::test]
async fn committed_contract_repair_retries_after_restart_without_a_replacement_alert() {
    let database = TemporaryDatabase::new().await;
    let store = database.store().await;
    store
        .upsert_contract_subscription(&contract_subscription(
            "durable-repair",
            ContractItemDirection::Offered,
            vec![587],
            vec![],
            ContractEventAction::PostAndPingEveryone,
        ))
        .await
        .expect("persist the delivery subscription");
    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("connect to seed the original sent delivery");
    let original_message = serde_json::json!({
        "title": "Type 587 listed",
        "description": "original render",
        "fields": [],
    });
    let delivery_id = sqlx::query_scalar::<_, i64>(
        "INSERT INTO contract_outbound_deliveries (guild_id, channel_id, subscription_id, contract_id, event_kind, event, message, ping, ping_type, status, delivery_nonce, discord_message_id) VALUES (42, 77, 'durable-repair', 45, 'listed', '{}'::jsonb, $1, TRUE, 'everyone', 'sent', 'ci-durable-repair', 'original-message') RETURNING id",
    )
    .bind(original_message)
    .fetch_one(&pool)
    .await
    .expect("seed original sent delivery");
    pool.close().await;

    let corrected = ContractNotificationMessage {
        title: "Rifter listed".to_string(),
        description: Some("corrected render".to_string()),
        fields: vec![],
        presentation_revision: CONTRACT_NOTIFICATION_PRESENTATION_REVISION,
        author: None,
        thumbnail_url: None,
        footer: None,
        timestamp: None,
    };
    assert!(store
        .prepare_delivery_repair(delivery_id, corrected.clone())
        .await
        .expect("commit the desired correction before Discord"));
    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("inspect committed repair state before adapter dispatch");
    let persisted: (String, Value) = sqlx::query_as(
        "SELECT repair_status, desired_message FROM contract_outbound_deliveries WHERE id = $1",
    )
    .bind(delivery_id)
    .fetch_one(&pool)
    .await
    .expect("read durable desired repair state");
    assert_eq!(persisted.0, "pending");
    assert_eq!(
        serde_json::from_value::<ContractNotificationMessage>(persisted.1)
            .expect("deserialize desired repair message"),
        corrected
    );
    pool.close().await;

    let initial_adapter = Arc::new(ScriptedRepairDelivery {
        sent: StdMutex::new(Vec::new()),
        edits: StdMutex::new(Vec::new()),
        edit_outcomes: StdMutex::new(vec![
            Err(ContractDeliveryError::transient("Discord rate limited")),
            Err(ContractDeliveryError::transient("Discord rate limited")),
            Err(ContractDeliveryError::transient("Discord rate limited")),
            Err(ContractDeliveryError::transient("Discord rate limited")),
        ]),
    });
    let repair_clock = Arc::new(FixedDeliveryClock(StdMutex::new(
        Utc.with_ymd_and_hms(2026, 8, 18, 12, 0, 0).unwrap(),
    )));
    assert!(
        ContractCollector::new(store.clone(), Arc::new(FailingContractEsi))
            .with_notifications(
                Arc::new(StaticShipGroups(HashMap::new())),
                initial_adapter.clone(),
            )
            .with_delivery_clock(repair_clock.clone())
            .collect_cycle()
            .await
            .is_err()
    );
    assert_eq!(initial_adapter.sent.lock().unwrap().len(), 0);
    assert_eq!(initial_adapter.edits.lock().unwrap().len(), 1);
    let inspection = store
        .inspect_contract_delivery(delivery_id)
        .await
        .expect("inspect persisted repair backoff")
        .expect("repair remains durable");
    assert_eq!(
        inspection.next_repair_attempt_at,
        Some(Utc.with_ymd_and_hms(2026, 8, 18, 12, 0, 5).unwrap())
    );

    let restarted_adapter = Arc::new(ScriptedRepairDelivery {
        sent: StdMutex::new(Vec::new()),
        edits: StdMutex::new(Vec::new()),
        edit_outcomes: StdMutex::new(vec![Ok(())]),
    });
    assert!(
        ContractCollector::new(database.store().await, Arc::new(FailingContractEsi))
            .with_notifications(
                Arc::new(StaticShipGroups(HashMap::new())),
                restarted_adapter.clone(),
            )
            .with_delivery_clock(repair_clock.clone())
            .collect_cycle()
            .await
            .is_err()
    );
    assert_eq!(restarted_adapter.sent.lock().unwrap().len(), 0);
    let edits = restarted_adapter.edits.lock().unwrap();
    assert!(
        edits.is_empty(),
        "restart must honor the persisted retry deadline"
    );
    drop(edits);
    *repair_clock.0.lock().unwrap() += chrono::Duration::seconds(5);
    let recovered_adapter = Arc::new(ScriptedRepairDelivery {
        sent: StdMutex::new(Vec::new()),
        edits: StdMutex::new(Vec::new()),
        edit_outcomes: StdMutex::new(vec![Ok(())]),
    });
    assert!(
        ContractCollector::new(database.store().await, Arc::new(FailingContractEsi))
            .with_notifications(
                Arc::new(StaticShipGroups(HashMap::new())),
                recovered_adapter.clone(),
            )
            .with_delivery_clock(repair_clock)
            .collect_cycle()
            .await
            .is_err()
    );
    let edits = recovered_adapter.edits.lock().unwrap();
    assert_eq!(edits.len(), 1);
    assert_eq!(edits[0].discord_message_id, "original-message");
    assert_eq!(edits[0].message, corrected);
    drop(edits);
    let records = database
        .store()
        .await
        .delivery_records()
        .await
        .expect("read repaired delivery");
    assert_eq!(records.len(), 1);
    assert_eq!(records[0].id, delivery_id);
    assert_eq!(records[0].status, DeliveryStatus::Sent);
    assert_eq!(
        records[0].discord_message_id.as_deref(),
        Some("original-message")
    );

    database.destroy().await;
}

#[tokio::test]
async fn permanent_contract_repair_is_critical_and_only_the_operator_can_requeue_it() {
    let database = TemporaryDatabase::new().await;
    let store = database.store().await;
    store
        .upsert_contract_subscription(&contract_subscription(
            "operator-repair",
            ContractItemDirection::Offered,
            vec![587],
            vec![],
            ContractEventAction::PostAndPingEveryone,
        ))
        .await
        .expect("persist the delivery subscription");
    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("connect to seed the sent delivery");
    let delivery_id = sqlx::query_scalar::<_, i64>(
        "INSERT INTO contract_outbound_deliveries (guild_id, channel_id, subscription_id, contract_id, event_kind, event, message, ping, ping_type, status, delivery_nonce, discord_message_id) VALUES (42, 77, 'operator-repair', 45, 'listed', '{}'::jsonb, '{\"title\":\"Type 587 listed\",\"fields\":[]}', TRUE, 'everyone', 'sent', 'ci-operator-repair', 'original-operator-message') RETURNING id",
    )
    .fetch_one(&pool)
    .await
    .expect("seed sent delivery");
    pool.close().await;
    store
        .prepare_delivery_repair(
            delivery_id,
            ContractNotificationMessage {
                title: "Rifter listed".to_string(),
                description: Some("repaired operator render".to_string()),
                fields: vec![],
                presentation_revision: CONTRACT_NOTIFICATION_PRESENTATION_REVISION,
                author: None,
                thumbnail_url: None,
                footer: None,
                timestamp: None,
            },
        )
        .await
        .expect("commit desired repair");

    let permanent_adapter = Arc::new(ScriptedRepairDelivery {
        sent: StdMutex::new(Vec::new()),
        edits: StdMutex::new(Vec::new()),
        edit_outcomes: StdMutex::new(vec![Err(ContractDeliveryError::permanent(
            "Missing Permissions",
        ))]),
    });
    assert!(
        ContractCollector::new(store.clone(), Arc::new(FailingContractEsi))
            .with_notifications(
                Arc::new(StaticShipGroups(HashMap::new())),
                permanent_adapter.clone(),
            )
            .collect_cycle()
            .await
            .is_err()
    );
    assert_eq!(permanent_adapter.sent.lock().unwrap().len(), 0);
    assert_eq!(permanent_adapter.edits.lock().unwrap().len(), 1);
    assert_eq!(
        store
            .delivery_failure(delivery_id)
            .await
            .expect("read permanent repair failure"),
        Some((
            DeliveryFailureKind::Permanent,
            "Missing Permissions".to_string()
        ))
    );
    let clock = Arc::new(FixedHealthClock(StdMutex::new(
        Utc.with_ymd_and_hms(2026, 8, 18, 12, 0, 0).unwrap(),
    )));
    let health = HealthCycle::new(store.clone(), clock.clone())
        .run_once()
        .await
        .expect("evaluate permanent repair health evidence");
    assert!(health.checks.iter().any(|check| {
        check.key == "permanent_delivery_failure" && check.status == HealthStatus::Critical
    }));

    let delivery_id_value = delivery_id.to_string();
    let unauthorized = execute_operator_delivery_cli(
        &store,
        &[
            "requeue",
            "--id",
            &delivery_id_value,
            "--actor",
            "discord:untrusted",
        ],
        clock.now(),
    )
    .await
    .expect_err("an unauthorized actor cannot requeue the permanent repair");
    assert!(unauthorized.contains("not authorized"));
    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("inspect unauthorized requeue state");
    let unchanged: (String, String, i64) = sqlx::query_as(
        "SELECT status, repair_status, (SELECT count(*) FROM contract_delivery_audit WHERE delivery_id = $1) FROM contract_outbound_deliveries WHERE id = $1",
    )
    .bind(delivery_id)
    .fetch_one(&pool)
    .await
    .expect("read unchanged permanent repair");
    assert_eq!(
        unchanged,
        ("failed".to_string(), "permanent".to_string(), 0)
    );
    pool.close().await;

    execute_operator_delivery_cli(
        &store,
        &[
            "inspect",
            "--id",
            &delivery_id_value,
            "--actor",
            CONTRACT_DELIVERY_OPERATOR_ACTOR,
        ],
        clock.now(),
    )
    .await
    .expect("operator can inspect the permanent repair");
    execute_operator_delivery_cli(
        &store,
        &[
            "requeue",
            "--id",
            &delivery_id_value,
            "--actor",
            CONTRACT_DELIVERY_OPERATOR_ACTOR,
        ],
        clock.now(),
    )
    .await
    .expect("operator requeues the original repair after remediation");
    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("inspect requeued repair state");
    let requeued: (String, String, String, bool, String, i64) = sqlx::query_as(
        "SELECT status, repair_status, discord_message_id, ping, ping_type, (SELECT count(*) FROM contract_delivery_audit WHERE delivery_id = $1 AND action = 'requeued' AND actor = $2) FROM contract_outbound_deliveries WHERE id = $1",
    )
    .bind(delivery_id)
    .bind(CONTRACT_DELIVERY_OPERATOR_ACTOR)
    .fetch_one(&pool)
    .await
    .expect("read requeued repair state");
    assert_eq!(
        requeued,
        (
            "sent".to_string(),
            "pending".to_string(),
            "original-operator-message".to_string(),
            true,
            "everyone".to_string(),
            1,
        )
    );
    pool.close().await;

    let recovered_adapter = Arc::new(ScriptedRepairDelivery {
        sent: StdMutex::new(Vec::new()),
        edits: StdMutex::new(Vec::new()),
        edit_outcomes: StdMutex::new(vec![Ok(())]),
    });
    assert!(
        ContractCollector::new(database.store().await, Arc::new(FailingContractEsi))
            .with_notifications(
                Arc::new(StaticShipGroups(HashMap::new())),
                recovered_adapter.clone(),
            )
            .collect_cycle()
            .await
            .is_err()
    );
    assert!(recovered_adapter.sent.lock().unwrap().is_empty());
    assert_eq!(recovered_adapter.edits.lock().unwrap().len(), 1);
    assert_eq!(
        database
            .store()
            .await
            .delivery_records()
            .await
            .expect("read recovered delivery")[0]
            .discord_message_id
            .as_deref(),
        Some("original-operator-message")
    );

    database.destroy().await;
}

fn run_contract_delivery_cli(
    database_url: &str,
    operator_token_sha256: &str,
    token_from_stdin: Option<&str>,
    arguments: &[&str],
) -> std::process::Output {
    let mut command = Command::new(env!("CARGO_BIN_EXE_killbot-rust"));
    command
        .arg("contract-delivery")
        .args(arguments)
        .env("CONTRACT_DATABASE_URL", database_url)
        .env(
            "CONTRACT_DELIVERY_OPERATOR_ID",
            CONTRACT_DELIVERY_OPERATOR_ACTOR,
        )
        .env(
            "CONTRACT_DELIVERY_OPERATOR_TOKEN_SHA256",
            operator_token_sha256,
        )
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    let mut child = command.spawn().expect("launch contract-delivery CLI");
    if let Some(token) = token_from_stdin {
        child
            .stdin
            .as_mut()
            .expect("CLI stdin is piped")
            .write_all(token.as_bytes())
            .expect("write capability token to CLI stdin");
    }
    drop(child.stdin.take());
    child
        .wait_with_output()
        .expect("wait for contract-delivery CLI")
}

fn cli_output(output: &std::process::Output) -> String {
    format!(
        "{}{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    )
}

fn rerender_test_event(contract_id: i64, kind: ContractEventKind) -> ContractEvent {
    let acceptance_evidence = match kind {
        ContractEventKind::SaleConfirmed => Some(ContractAcceptanceEvidence {
            last_public_observed_at: Utc.with_ymd_and_hms(2026, 8, 14, 12, 0, 0).unwrap(),
            absence_observed_at: Utc.with_ymd_and_hms(2026, 8, 14, 12, 5, 0).unwrap(),
            evidence_response_at: Utc.with_ymd_and_hms(2026, 8, 14, 12, 6, 0).unwrap(),
            provenance: Some(
                killbot_rust::contract_intelligence::ContractAcceptanceProvenance::AcceptedByPlayer,
            ),
        }),
        ContractEventKind::ClosedOutcomeUnknown => Some(ContractAcceptanceEvidence {
            last_public_observed_at: Utc.with_ymd_and_hms(2026, 8, 14, 12, 0, 0).unwrap(),
            absence_observed_at: Utc.with_ymd_and_hms(2026, 8, 14, 12, 5, 0).unwrap(),
            evidence_response_at: Utc.with_ymd_and_hms(2026, 8, 14, 12, 6, 0).unwrap(),
            provenance: Some(
                killbot_rust::contract_intelligence::ContractAcceptanceProvenance::NoContent,
            ),
        }),
        _ => None,
    };
    ContractEvent {
        region_id: 10_000_002,
        kind,
        contract: item_exchange_contract(contract_id),
        offered_items: vec![offered_ship(contract_id)],
        requested_items: vec![],
        context: ContractObservationContext::default(),
        acceptance_evidence,
        embed_context: ContractEmbedContext {
            item_names: BTreeMap::from([(587, "Rifter".to_string())]),
            ..ContractEmbedContext::default()
        },
    }
}

const RERENDER_TEST_MESSAGE_SNOWFLAKE_BASE: u64 = 1_115_807_643_748_012_000;

fn rerender_test_discord_message_id(offset: u64) -> String {
    (RERENDER_TEST_MESSAGE_SNOWFLAKE_BASE + offset).to_string()
}

#[tokio::test]
async fn contract_delivery_rerender_skips_and_reports_malformed_rows_before_the_limit_for_dry_run_and_queue(
) {
    let database = TemporaryDatabase::new().await;
    let store = database.store().await;
    store
        .upsert_contract_subscription(&contract_subscription(
            "rerender-malformed",
            ContractItemDirection::Offered,
            vec![587],
            vec![],
            ContractEventAction::Post,
        ))
        .await
        .expect("persist rerender subscription");
    store
        .upsert_contract_subscription(&contract_subscription(
            "rerender-invalid-subscription",
            ContractItemDirection::Offered,
            vec![587],
            vec![],
            ContractEventAction::Post,
        ))
        .await
        .expect("persist rerender subscription to corrupt");
    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("connect to seed malformed rerender history");
    let legacy_message = serde_json::json!({
        "title": "Legacy Rifter listed",
        "description": null,
        "fields": []
    });
    let insert = "INSERT INTO contract_outbound_deliveries (guild_id, channel_id, subscription_id, contract_id, event_kind, event, message, ping, ping_type, status, delivery_nonce, discord_message_id) VALUES (42, 77, 'rerender-malformed', $1, 'listed', $2, $3, TRUE, 'everyone', 'sent', CONCAT('rerender-malformed-', $1), CONCAT('1115807643748012', LPAD($1::TEXT, 3, '0'))) RETURNING id";
    let malformed_event_id = sqlx::query_scalar::<_, i64>(insert)
        .bind(44_i64)
        .bind(serde_json::json!({}))
        .bind(&legacy_message)
        .fetch_one(&pool)
        .await
        .expect("seed malformed retained event");
    let malformed_message_id = sqlx::query_scalar::<_, i64>(insert)
        .bind(46_i64)
        .bind(
            serde_json::to_value(rerender_test_event(46, ContractEventKind::Listed))
                .expect("serialize retained event"),
        )
        .bind(serde_json::json!({"title": 7, "description": null, "fields": []}))
        .fetch_one(&pool)
        .await
        .expect("seed malformed retained message");
    let empty_discord_message_id = sqlx::query_scalar::<_, i64>(insert)
        .bind(47_i64)
        .bind(
            serde_json::to_value(rerender_test_event(47, ContractEventKind::Listed))
                .expect("serialize retained event"),
        )
        .bind(&legacy_message)
        .fetch_one(&pool)
        .await
        .expect("seed retained event with an empty Discord message identity");
    let non_numeric_discord_message_id = sqlx::query_scalar::<_, i64>(insert)
        .bind(48_i64)
        .bind(
            serde_json::to_value(rerender_test_event(48, ContractEventKind::Listed))
                .expect("serialize retained event"),
        )
        .bind(&legacy_message)
        .fetch_one(&pool)
        .await
        .expect("seed retained event with a nonnumeric Discord message identity");
    let zero_discord_message_id = sqlx::query_scalar::<_, i64>(insert)
        .bind(49_i64)
        .bind(
            serde_json::to_value(rerender_test_event(49, ContractEventKind::Listed))
                .expect("serialize retained event"),
        )
        .bind(&legacy_message)
        .fetch_one(&pool)
        .await
        .expect("seed retained event with a zero Discord message identity");
    sqlx::query("UPDATE contract_outbound_deliveries SET discord_message_id = CASE id WHEN $1 THEN '' WHEN $2 THEN 'not-a-discord-message-id' ELSE '0' END WHERE id IN ($1, $2, $3)")
        .bind(empty_discord_message_id)
        .bind(non_numeric_discord_message_id)
        .bind(zero_discord_message_id)
        .execute(&pool)
        .await
        .expect("seed invalid Discord message identities");
    let retained_event_identity_mismatch_id = sqlx::query_scalar::<_, i64>(insert)
        .bind(45_i64)
        .bind(
            serde_json::to_value(rerender_test_event(46, ContractEventKind::Listed))
                .expect("serialize a valid but mismatched retained event"),
        )
        .bind(&legacy_message)
        .fetch_one(&pool)
        .await
        .expect("seed retained event identity mismatch");
    let invalid_subscription_id = sqlx::query_scalar::<_, i64>(
        "INSERT INTO contract_outbound_deliveries (guild_id, channel_id, subscription_id, contract_id, event_kind, event, message, ping, ping_type, status, delivery_nonce, discord_message_id) VALUES (42, 77, 'rerender-invalid-subscription', 51, 'listed', $1, $2, TRUE, 'everyone', 'sent', 'rerender-invalid-subscription-51', '1115807643748012051') RETURNING id",
    )
    .bind(
        serde_json::to_value(rerender_test_event(51, ContractEventKind::Listed))
            .expect("serialize retained event for malformed subscription"),
    )
    .bind(&legacy_message)
    .fetch_one(&pool)
    .await
    .expect("seed delivery with persisted subscription");
    sqlx::query("UPDATE contract_subscriptions SET description = ' ' WHERE guild_id = 42 AND channel_id = 77 AND subscription_id = 'rerender-invalid-subscription'")
        .execute(&pool)
        .await
        .expect("corrupt retained subscription validation invariant");
    let valid_id = sqlx::query_scalar::<_, i64>(insert)
        .bind(50_i64)
        .bind(
            serde_json::to_value(rerender_test_event(50, ContractEventKind::Listed))
                .expect("serialize retained event"),
        )
        .bind(&legacy_message)
        .fetch_one(&pool)
        .await
        .expect("seed valid retained event after malformed identities");
    pool.close().await;

    let token = "rerender-malformed-test-token-not-for-argv";
    let digest = format!("{:x}", Sha256::digest(token.as_bytes()));
    for mode in ["--dry-run", "--queue"] {
        let output = run_contract_delivery_cli(
            &database.url,
            &digest,
            Some(token),
            &["rerender", "--channel", "77", "--limit", "1", mode],
        );
        assert!(output.status.success(), "{}", cli_output(&output));
        let report: Value = serde_json::from_slice(&output.stdout).expect("rerender JSON result");
        assert_eq!(report["eligible_count"], 1);
        assert_eq!(report["candidates"][0]["delivery_id"], valid_id);
        assert_eq!(report["excluded_count"], 7);
        assert_eq!(
            report["excluded"]
                .as_array()
                .expect("malformed retained rows are reported")
                .iter()
                .map(|row| (row["delivery_id"].as_i64(), row["reason"].as_str()))
                .collect::<Vec<_>>(),
            vec![
                (Some(malformed_event_id), Some("invalid_retained_event")),
                (Some(malformed_message_id), Some("invalid_retained_message")),
                (
                    Some(empty_discord_message_id),
                    Some("invalid_discord_message_identity"),
                ),
                (
                    Some(non_numeric_discord_message_id),
                    Some("invalid_discord_message_identity"),
                ),
                (
                    Some(zero_discord_message_id),
                    Some("invalid_discord_message_identity"),
                ),
                (
                    Some(retained_event_identity_mismatch_id),
                    Some("retained_event_identity_mismatch"),
                ),
                (
                    Some(invalid_subscription_id),
                    Some("invalid_retained_subscription")
                ),
            ]
        );
    }

    for mode in ["--dry-run", "--queue"] {
        let explicit = run_contract_delivery_cli(
            &database.url,
            &digest,
            Some(token),
            &[
                "rerender",
                "--channel",
                "77",
                "--delivery-ids",
                &retained_event_identity_mismatch_id.to_string(),
                mode,
            ],
        );
        assert!(!explicit.status.success());
        assert!(cli_output(&explicit).contains("selected deliveries have malformed retained data"));
    }

    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("inspect rerender queue after malformed rows");
    let states: Vec<(i64, String, Option<Value>, i64)> = sqlx::query_as(
        "SELECT id, repair_status, desired_message, (SELECT count(*) FROM contract_delivery_audit WHERE delivery_id = contract_outbound_deliveries.id AND action = 'rerendered') FROM contract_outbound_deliveries ORDER BY id",
    )
    .fetch_all(&pool)
    .await
    .expect("read rerender states");
    assert_eq!(states.len(), 8);
    assert_eq!(states[0], (malformed_event_id, "none".to_string(), None, 0));
    assert_eq!(
        states[1],
        (malformed_message_id, "none".to_string(), None, 0)
    );
    assert_eq!(
        states[2],
        (empty_discord_message_id, "none".to_string(), None, 0)
    );
    assert_eq!(
        states[3],
        (non_numeric_discord_message_id, "none".to_string(), None, 0)
    );
    assert_eq!(
        states[4],
        (zero_discord_message_id, "none".to_string(), None, 0)
    );
    assert_eq!(
        states[5],
        (
            retained_event_identity_mismatch_id,
            "none".to_string(),
            None,
            0
        )
    );
    assert_eq!(
        states[6],
        (invalid_subscription_id, "none".to_string(), None, 0)
    );
    assert_eq!(states[7].0, valid_id);
    assert_eq!(states[7].1, "pending");
    assert!(states[7].2.is_some());
    assert_eq!(states[7].3, 1);
    assert_eq!(
        states[7]
            .2
            .as_ref()
            .and_then(|message| message.get("presentation_revision"))
            .and_then(Value::as_u64),
        Some(CONTRACT_NOTIFICATION_PRESENTATION_REVISION.into())
    );
    pool.close().await;
    database.destroy().await;
}

