#[tokio::test]
async fn historical_rerender_batch_stops_after_a_permanent_edit_failure_and_leaves_later_repairs_durable(
) {
    let database = TemporaryDatabase::new().await;
    let store = database.store().await;
    store
        .upsert_contract_subscription(&contract_subscription(
            "rerender-stop-on-permanent",
            ContractItemDirection::Offered,
            vec![587],
            vec![],
            ContractEventAction::Post,
        ))
        .await
        .expect("persist rerender stop subscription");
    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("connect to seed rerender repair batch");
    let original = serde_json::json!({"title":"Legacy listing","fields":[]});
    let first_id = sqlx::query_scalar::<_, i64>(
        "INSERT INTO contract_outbound_deliveries (guild_id, channel_id, subscription_id, contract_id, event_kind, event, message, ping, ping_type, status, delivery_nonce, discord_message_id) VALUES (42, 77, 'rerender-stop-on-permanent', 45, 'listed', '{}'::jsonb, $1, FALSE, 'here', 'sent', 'ci-rerender-stop-first', 'original-first') RETURNING id",
    )
    .bind(&original)
    .fetch_one(&pool)
    .await
    .expect("seed first retained rerender");
    let second_id = sqlx::query_scalar::<_, i64>(
        "INSERT INTO contract_outbound_deliveries (guild_id, channel_id, subscription_id, contract_id, event_kind, event, message, ping, ping_type, status, delivery_nonce, discord_message_id) VALUES (42, 77, 'rerender-stop-on-permanent', 46, 'listed', '{}'::jsonb, $1, FALSE, 'here', 'sent', 'ci-rerender-stop-second', 'original-second') RETURNING id",
    )
    .bind(&original)
    .fetch_one(&pool)
    .await
    .expect("seed later retained rerender");
    pool.close().await;
    for (delivery_id, title) in [
        (first_id, "First correction"),
        (second_id, "Later correction"),
    ] {
        store
            .prepare_delivery_repair(
                delivery_id,
                ContractNotificationMessage {
                    title: title.to_string(),
                    description: None,
                    fields: vec![],
                    presentation_revision: CONTRACT_NOTIFICATION_PRESENTATION_REVISION,
                    author: None,
                    thumbnail_url: None,
                    footer: None,
                    timestamp: None,
                },
            )
            .await
            .expect("queue durable historical repair");
    }

    let delivery = Arc::new(ScriptedRepairDelivery {
        sent: StdMutex::new(Vec::new()),
        edits: StdMutex::new(Vec::new()),
        edit_outcomes: StdMutex::new(vec![Err(ContractDeliveryError::permanent_delivery(
            "Discord HTTP 404, JSON code 10008",
        ))]),
    });
    ContractCollector::new(store.clone(), Arc::new(FailingContractEsi))
        .with_notifications(Arc::new(StaticShipGroups(HashMap::new())), delivery.clone())
        .reconcile_proximity_notifications()
        .await
        .expect("run one durable repair dispatch batch");

    let edits = delivery.edits.lock().unwrap();
    assert_eq!(
        edits.len(),
        1,
        "a permanent edit failure stops this rerender batch"
    );
    assert_eq!(edits[0].delivery_id, first_id);
    drop(edits);
    assert!(delivery.sent.lock().unwrap().is_empty());
    let first = store
        .inspect_contract_delivery(first_id)
        .await
        .expect("inspect permanent rerender")
        .expect("first rerender remains recorded");
    assert_eq!(first.status, DeliveryStatus::Failed);
    assert_eq!(
        first.repair_failure_kind,
        Some(DeliveryFailureKind::Permanent)
    );
    let second = store
        .inspect_contract_delivery(second_id)
        .await
        .expect("inspect unattempted rerender")
        .expect("later rerender remains durable");
    assert_eq!(second.status, DeliveryStatus::Sent);
    assert_eq!(
        second.repair_status,
        killbot_rust::contract_intelligence::ContractRepairStatus::Pending
    );
    assert_eq!(
        second
            .desired_message
            .as_ref()
            .map(|message| message.title.as_str()),
        Some("Later correction")
    );
    assert_eq!(
        second.discord_message_id.as_deref(),
        Some("original-second")
    );

    database.destroy().await;
}

#[tokio::test]
async fn historical_rerender_batch_stops_at_a_retry_after_boundary_until_the_deadline() {
    let database = TemporaryDatabase::new().await;
    let store = database.store().await;
    store
        .upsert_contract_subscription(&contract_subscription(
            "rerender-stop-on-retry-after",
            ContractItemDirection::Offered,
            vec![587],
            vec![],
            ContractEventAction::Post,
        ))
        .await
        .expect("persist rerender retry boundary subscription");
    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("connect to seed rerender retry boundary batch");
    let original = serde_json::json!({"title":"Legacy listing","fields":[]});
    let first_id = sqlx::query_scalar::<_, i64>(
        "INSERT INTO contract_outbound_deliveries (guild_id, channel_id, subscription_id, contract_id, event_kind, event, message, ping, ping_type, status, delivery_nonce, discord_message_id) VALUES (42, 77, 'rerender-stop-on-retry-after', 45, 'listed', '{}'::jsonb, $1, FALSE, 'here', 'sent', 'ci-rerender-retry-first', '1115807643748012001') RETURNING id",
    )
    .bind(&original)
    .fetch_one(&pool)
    .await
    .expect("seed first retained rerender");
    let second_id = sqlx::query_scalar::<_, i64>(
        "INSERT INTO contract_outbound_deliveries (guild_id, channel_id, subscription_id, contract_id, event_kind, event, message, ping, ping_type, status, delivery_nonce, discord_message_id) VALUES (42, 77, 'rerender-stop-on-retry-after', 46, 'listed', '{}'::jsonb, $1, FALSE, 'here', 'sent', 'ci-rerender-retry-second', '1115807643748012002') RETURNING id",
    )
    .bind(&original)
    .fetch_one(&pool)
    .await
    .expect("seed later retained rerender");
    pool.close().await;
    for (delivery_id, title) in [
        (first_id, "First correction"),
        (second_id, "Later correction"),
    ] {
        store
            .prepare_delivery_repair(
                delivery_id,
                ContractNotificationMessage {
                    title: title.to_string(),
                    description: None,
                    fields: vec![],
                    presentation_revision: CONTRACT_NOTIFICATION_PRESENTATION_REVISION,
                    author: None,
                    thumbnail_url: None,
                    footer: None,
                    timestamp: None,
                },
            )
            .await
            .expect("queue durable historical repair");
    }

    let wire = ControlledHttpServer::start(
        vec![
            WireReply {
                status: 429,
                headers: vec![("Retry-After", "60")],
                body: r#"{"retry_after":60.0,"global":false}"#,
            },
            WireReply {
                status: 200,
                headers: vec![],
                body: "{}",
            },
            WireReply {
                status: 200,
                headers: vec![],
                body: "{}",
            },
        ],
        WireReply {
            status: 500,
            headers: vec![],
            body: r#"{"code":0,"message":"unexpected rerender retry"}"#,
        },
    );
    let delivery = Arc::new(DiscordContractDelivery::new_with_edit_api_base(
        Arc::new(Http::new("controlled-rerender-retry-token")),
        wire.base_url.trim_end_matches('/').to_string(),
    ));
    let attempted_at = Utc::now();
    ContractCollector::new(store.clone(), Arc::new(FailingContractEsi))
        .with_notifications(Arc::new(StaticShipGroups(HashMap::new())), delivery.clone())
        .with_delivery_clock(Arc::new(FixedDeliveryClock(StdMutex::new(attempted_at))))
        .reconcile_proximity_notifications()
        .await
        .expect("persist the retryable rerender failure");

    let requests = wire.requests.lock().unwrap().clone();
    assert_eq!(
        requests.len(),
        1,
        "the retry-after boundary stops the historical rerender batch"
    );
    assert!(requests[0].starts_with("PATCH /channels/77/messages/1115807643748012001 HTTP/1.1\r\n"));
    let first = store
        .inspect_contract_delivery(first_id)
        .await
        .expect("inspect retrying rerender")
        .expect("first rerender remains recorded");
    let retry_at = first
        .next_repair_attempt_at
        .expect("the 429 Retry-After becomes a durable future retry deadline");
    assert!(retry_at >= attempted_at + chrono::Duration::seconds(59));
    let second = store
        .inspect_contract_delivery(second_id)
        .await
        .expect("inspect unattempted rerender")
        .expect("later rerender remains durable");
    assert_eq!(second.repair_attempt_count, 0);
    assert_eq!(
        second.repair_status,
        killbot_rust::contract_intelligence::ContractRepairStatus::Pending
    );
    assert_eq!(second.next_repair_attempt_at, None);

    ContractCollector::new(database.store().await, Arc::new(FailingContractEsi))
        .with_notifications(Arc::new(StaticShipGroups(HashMap::new())), delivery.clone())
        .with_delivery_clock(Arc::new(FixedDeliveryClock(StdMutex::new(
            retry_at - chrono::Duration::seconds(1),
        ))))
        .reconcile_proximity_notifications()
        .await
        .expect("a restarted rerender dispatcher honors the retry boundary");
    assert_eq!(wire.requests.lock().unwrap().len(), 1);

    ContractCollector::new(database.store().await, Arc::new(FailingContractEsi))
        .with_notifications(Arc::new(StaticShipGroups(HashMap::new())), delivery)
        .with_delivery_clock(Arc::new(FixedDeliveryClock(StdMutex::new(retry_at))))
        .reconcile_proximity_notifications()
        .await
        .expect("the rerender batch resumes at the retry deadline");
    let requests = wire.requests.lock().unwrap().clone();
    assert_eq!(requests.len(), 3);
    assert!(requests[1].starts_with("PATCH /channels/77/messages/1115807643748012001 HTTP/1.1\r\n"));
    assert!(requests[2].starts_with("PATCH /channels/77/messages/1115807643748012002 HTTP/1.1\r\n"));
    for delivery_id in [first_id, second_id] {
        let inspection = store
            .inspect_contract_delivery(delivery_id)
            .await
            .expect("inspect resumed rerender")
            .expect("rerender remains recorded");
        assert_eq!(
            inspection.repair_status,
            killbot_rust::contract_intelligence::ContractRepairStatus::None
        );
    }
    wire.finish();
    database.destroy().await;
}

#[tokio::test]
async fn contract_delivery_cli_requires_stdin_capability_and_audits_only_the_configured_operator() {
    let database = TemporaryDatabase::new().await;
    let store = database.store().await;
    store
        .upsert_contract_subscription(&contract_subscription(
            "operator-cli-capability",
            ContractItemDirection::Offered,
            vec![587],
            vec![],
            ContractEventAction::Post,
        ))
        .await
        .expect("persist the operator CLI subscription");
    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("connect to seed a permanent delivery failure");
    let delivery_id = sqlx::query_scalar::<_, i64>(
        "INSERT INTO contract_outbound_deliveries (guild_id, channel_id, subscription_id, contract_id, event_kind, event, message, ping, ping_type, status, failure_kind, delivery_nonce) VALUES (42, 77, 'operator-cli-capability', 45, 'listed', '{}'::jsonb, '{\"title\":\"CLI repair\",\"fields\":[]}', FALSE, 'here', 'failed', 'permanent', 'ci-operator-cli-capability') RETURNING id",
    )
    .fetch_one(&pool)
    .await
    .expect("seed a permanent delivery failure");
    pool.close().await;

    let token = "contract-delivery-test-token-not-for-argv";
    let token_digest = format!("{:x}", Sha256::digest(token.as_bytes()));
    let delivery_id_value = delivery_id.to_string();
    let inspect_arguments = ["inspect", "--id", delivery_id_value.as_str()];

    let public_actor = run_contract_delivery_cli(
        &database.url,
        &token_digest,
        Some(token),
        &[
            "inspect",
            "--id",
            &delivery_id_value,
            "--actor",
            "discord:000000000000000001",
        ],
    );
    assert!(!public_actor.status.success());
    assert!(cli_output(&public_actor).contains("does not accept --actor"));

    let absent_token =
        run_contract_delivery_cli(&database.url, &token_digest, None, &inspect_arguments);
    assert!(!absent_token.status.success());
    assert!(cli_output(&absent_token).contains("capability rejected"));

    let wrong_token = run_contract_delivery_cli(
        &database.url,
        &token_digest,
        Some("wrong-contract-delivery-token"),
        &inspect_arguments,
    );
    assert!(!wrong_token.status.success());
    assert!(cli_output(&wrong_token).contains("capability rejected"));

    let oversized_token = "x".repeat(CONTRACT_DELIVERY_OPERATOR_TOKEN_MAX_BYTES + 1);
    let oversized = run_contract_delivery_cli(
        &database.url,
        &token_digest,
        Some(&oversized_token),
        &inspect_arguments,
    );
    assert!(!oversized.status.success());
    assert!(cli_output(&oversized).contains("capability rejected"));
    assert!(
        store
            .inspect_contract_delivery(delivery_id)
            .await
            .expect("inspect delivery after rejected oversized capability")
            .expect("seeded delivery remains available")
            .audit
            .is_empty(),
        "oversized stdin capability must not mutate the delivery or audit trail"
    );

    let inspected = run_contract_delivery_cli(
        &database.url,
        &token_digest,
        Some(token),
        &inspect_arguments,
    );
    assert!(inspected.status.success());
    assert!(cli_output(&inspected).contains("\"result\":\"inspected\""));

    let requeued = run_contract_delivery_cli(
        &database.url,
        &token_digest,
        Some(token),
        &["requeue", "--id", &delivery_id_value],
    );
    assert!(requeued.status.success());
    assert!(cli_output(&requeued).contains("\"result\":\"requeued\""));

    for output in [
        &public_actor,
        &absent_token,
        &wrong_token,
        &oversized,
        &inspected,
        &requeued,
    ] {
        assert!(
            !cli_output(output).contains(token),
            "the stdin capability token is never emitted"
        );
    }
    let inspection = store
        .inspect_contract_delivery(delivery_id)
        .await
        .expect("inspect delivery after CLI requeue")
        .expect("seeded delivery remains available");
    assert_eq!(inspection.status, DeliveryStatus::Prepared);
    assert_eq!(inspection.audit.len(), 1);
    assert_eq!(inspection.audit[0].actor, CONTRACT_DELIVERY_OPERATOR_ACTOR);
    assert!(!serde_json::to_string(&inspection)
        .expect("serialize delivery audit")
        .contains(token));

    database.destroy().await;
}

#[tokio::test]
async fn contract_delivery_inspection_serializes_typed_status_and_rejects_unknown_stored_status() {
    let database = TemporaryDatabase::new().await;
    let store = database.store().await;
    store
        .upsert_contract_subscription(&contract_subscription(
            "typed-inspection-status",
            ContractItemDirection::Offered,
            vec![587],
            vec![],
            ContractEventAction::Post,
        ))
        .await
        .expect("persist typed inspection subscription");
    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("connect to seed typed inspection delivery");
    let delivery_id = sqlx::query_scalar::<_, i64>(
        "INSERT INTO contract_outbound_deliveries (guild_id, channel_id, subscription_id, contract_id, event_kind, event, message, ping, ping_type, status, delivery_nonce) VALUES (42, 77, 'typed-inspection-status', 45, 'listed', '{}'::jsonb, '{\"title\":\"Typed inspection\",\"fields\":[]}', FALSE, 'here', 'sent', 'ci-typed-inspection-status') RETURNING id",
    )
    .fetch_one(&pool)
    .await
    .expect("seed sent typed inspection delivery");
    let inspection = store
        .inspect_contract_delivery(delivery_id)
        .await
        .expect("inspect valid typed status")
        .expect("seeded delivery exists");
    assert_eq!(inspection.status, DeliveryStatus::Sent);
    assert_eq!(
        serde_json::to_value(&inspection).expect("serialize typed delivery inspection")["status"],
        "sent"
    );

    sqlx::query("ALTER TABLE contract_outbound_deliveries DROP CONSTRAINT contract_outbound_deliveries_status_check")
        .execute(&pool)
        .await
        .expect("permit corrupted delivery status fixture");
    sqlx::query("UPDATE contract_outbound_deliveries SET status = 'unknown-status' WHERE id = $1")
        .bind(delivery_id)
        .execute(&pool)
        .await
        .expect("seed unknown delivery status");
    let error = store
        .inspect_contract_delivery(delivery_id)
        .await
        .expect_err("unknown persisted delivery status is rejected");
    assert!(error
        .to_string()
        .contains("unknown delivery status: unknown-status"));

    pool.close().await;
    database.destroy().await;
}

#[tokio::test]
async fn a_failed_contract_repair_does_not_block_an_unrelated_prepared_delivery() {
    let database = TemporaryDatabase::new().await;
    let store = database.store().await;
    for subscription_id in ["repair-isolation", "unrelated-isolation"] {
        store
            .upsert_contract_subscription(&contract_subscription(
                subscription_id,
                ContractItemDirection::Offered,
                vec![587],
                vec![],
                ContractEventAction::Post,
            ))
            .await
            .expect("persist isolation subscription");
    }
    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("connect to seed isolated deliveries");
    let repair_id = sqlx::query_scalar::<_, i64>(
        "INSERT INTO contract_outbound_deliveries (guild_id, channel_id, subscription_id, contract_id, event_kind, event, message, ping, ping_type, status, delivery_nonce, discord_message_id) VALUES (42, 77, 'repair-isolation', 45, 'listed', '{}'::jsonb, '{\"title\":\"Original repair\",\"fields\":[]}', FALSE, 'here', 'sent', 'ci-repair-isolation', 'repair-original-message') RETURNING id",
    )
    .fetch_one(&pool)
    .await
    .expect("seed sent repair delivery");
    let unrelated_id = sqlx::query_scalar::<_, i64>(
        "INSERT INTO contract_outbound_deliveries (guild_id, channel_id, subscription_id, contract_id, event_kind, event, message, ping, ping_type, status, delivery_nonce) VALUES (42, 77, 'unrelated-isolation', 46, 'listed', '{}'::jsonb, '{\"title\":\"Unrelated listing\",\"fields\":[]}', FALSE, 'here', 'prepared', 'ci-unrelated-isolation') RETURNING id",
    )
    .fetch_one(&pool)
    .await
    .expect("seed unrelated prepared delivery");
    pool.close().await;
    store
        .prepare_delivery_repair(
            repair_id,
            ContractNotificationMessage {
                title: "Corrected repair".to_string(),
                description: None,
                fields: vec![],
                presentation_revision: CONTRACT_NOTIFICATION_PRESENTATION_REVISION,
                author: None,
                thumbnail_url: None,
                footer: None,
                timestamp: None,
            },
        )
        .await
        .expect("commit the durable repair");
    let adapter = Arc::new(IsolatedRepairDelivery {
        sent: StdMutex::new(Vec::new()),
        edits: StdMutex::new(Vec::new()),
    });
    assert!(
        ContractCollector::new(store.clone(), Arc::new(FailingContractEsi))
            .with_notifications(Arc::new(StaticShipGroups(HashMap::new())), adapter.clone())
            .collect_cycle()
            .await
            .is_err()
    );
    assert_eq!(adapter.sent.lock().unwrap().len(), 1);
    assert_eq!(adapter.sent.lock().unwrap()[0].delivery_id, unrelated_id);
    assert_eq!(adapter.edits.lock().unwrap().len(), 1);
    let records = store
        .delivery_records()
        .await
        .expect("read isolated delivery records");
    assert_eq!(
        records
            .iter()
            .find(|record| record.id == repair_id)
            .expect("repair record")
            .status,
        DeliveryStatus::Failed
    );
    assert_eq!(
        records
            .iter()
            .find(|record| record.id == unrelated_id)
            .expect("unrelated record")
            .status,
        DeliveryStatus::Sent
    );

    database.destroy().await;
}

#[tokio::test]
async fn contract_repair_waits_for_a_persisted_platform_retry_deadline() {
    let database = TemporaryDatabase::new().await;
    let store = database.store().await;
    store
        .upsert_contract_subscription(&contract_subscription(
            "retry-deadline-repair",
            ContractItemDirection::Offered,
            vec![587],
            vec![],
            ContractEventAction::Post,
        ))
        .await
        .expect("persist the delivery subscription");
    let pool = PgPoolOptions::new()
        .max_connections(1)
        .connect(&database.url)
        .await
        .expect("connect to seed the sent delivery");
    let delivery_id = sqlx::query_scalar::<_, i64>(
        "INSERT INTO contract_outbound_deliveries (guild_id, channel_id, subscription_id, contract_id, event_kind, event, message, ping, ping_type, status, delivery_nonce, discord_message_id) VALUES (42, 77, 'retry-deadline-repair', 45, 'listed', '{}'::jsonb, '{\"title\":\"Type 587 listed\",\"fields\":[]}', FALSE, 'here', 'sent', 'ci-retry-deadline-repair', 'original-retry-message') RETURNING id",
    )
    .fetch_one(&pool)
    .await
    .expect("seed sent delivery");
    pool.close().await;
    store
        .prepare_delivery_repair(
            delivery_id,
            ContractNotificationMessage {
                title: "Rifter listed".to_string(),
                description: None,
                fields: vec![],
                presentation_revision: CONTRACT_NOTIFICATION_PRESENTATION_REVISION,
                author: None,
                thumbnail_url: None,
                footer: None,
                timestamp: None,
            },
        )
        .await
        .expect("commit desired repair");
    let attempted_at = Utc.with_ymd_and_hms(2026, 8, 18, 12, 0, 0).unwrap();
    let retry_at = attempted_at + chrono::Duration::seconds(60);
    let adapter = Arc::new(ScriptedRepairDelivery {
        sent: StdMutex::new(Vec::new()),
        edits: StdMutex::new(Vec::new()),
        edit_outcomes: StdMutex::new(vec![Err(ContractDeliveryError::transient_after(
            "Discord Retry-After",
            retry_at,
        ))]),
    });
    assert!(
        ContractCollector::new(store.clone(), Arc::new(FailingContractEsi))
            .with_notifications(Arc::new(StaticShipGroups(HashMap::new())), adapter.clone())
            .with_delivery_clock(Arc::new(FixedDeliveryClock(StdMutex::new(attempted_at))))
            .collect_cycle()
            .await
            .is_err()
    );
    assert_eq!(adapter.edits.lock().unwrap().len(), 1);
    let inspection = store
        .inspect_contract_delivery(delivery_id)
        .await
        .expect("inspect retry deadline")
        .expect("delivery remains durable");
    assert_eq!(inspection.next_repair_attempt_at, Some(retry_at));

    let before_retry = Arc::new(ScriptedRepairDelivery {
        sent: StdMutex::new(Vec::new()),
        edits: StdMutex::new(Vec::new()),
        edit_outcomes: StdMutex::new(vec![Ok(())]),
    });
    assert!(
        ContractCollector::new(database.store().await, Arc::new(FailingContractEsi))
            .with_notifications(
                Arc::new(StaticShipGroups(HashMap::new())),
                before_retry.clone(),
            )
            .with_delivery_clock(Arc::new(FixedDeliveryClock(StdMutex::new(
                retry_at - chrono::Duration::seconds(1),
            ))))
            .collect_cycle()
            .await
            .is_err(),
        "a restarted collector observes the durable retry deadline before editing"
    );
    assert!(before_retry.edits.lock().unwrap().is_empty());
    assert!(before_retry.sent.lock().unwrap().is_empty());

    let after_retry = Arc::new(ScriptedRepairDelivery {
        sent: StdMutex::new(Vec::new()),
        edits: StdMutex::new(Vec::new()),
        edit_outcomes: StdMutex::new(vec![Ok(())]),
    });
    assert!(
        ContractCollector::new(database.store().await, Arc::new(FailingContractEsi))
            .with_notifications(
                Arc::new(StaticShipGroups(HashMap::new())),
                after_retry.clone(),
            )
            .with_delivery_clock(Arc::new(FixedDeliveryClock(StdMutex::new(retry_at))))
            .collect_cycle()
            .await
            .is_err(),
        "the restarted collector performs the PATCH-equivalent durable edit at the deadline"
    );
    assert!(after_retry.sent.lock().unwrap().is_empty());
    assert_eq!(after_retry.edits.lock().unwrap().len(), 1);
    assert_eq!(
        after_retry.edits.lock().unwrap()[0].discord_message_id,
        "original-retry-message"
    );

    database.destroy().await;
}

